#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# HomeKeeper → Vercel. Local dev keeps PGlite in .env.local; every production value
# lives on Vercel. After this, tell Claude "done" to migrate/seed Neon and deploy.

VERCEL=(npx --yes vercel@latest)
ON_VERCEL=() # env vars confirmed on Vercel (production) this run

# Non-interactive vercel calls read stdin from /dev/null: with a TTY the CLI can stop at a
# prompt whose output we hide, which looks like a freeze.

# has_env NAME: true if NAME already exists in the Vercel project's production env.
has_env() {
  "${VERCEL[@]}" env ls production </dev/null 2>/dev/null | awk '{print $1}' | grep -qx "$1"
}

# vercel_env NAME VALUE: (re)sets NAME for production on Vercel.
vercel_env() {
  local name="$1" value="$2"
  "${VERCEL[@]}" env rm "$name" production --yes </dev/null >/dev/null 2>&1 || true
  if printf '%s' "$value" | "${VERCEL[@]}" env add "$name" production >/dev/null 2>&1; then
    ON_VERCEL+=("$name")
    printf '  %s✓ set%s %s on Vercel (production)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name (dashboard → Settings → Environment Variables → Production)")
    warn "couldn't set $name; add it in the dashboard later"
  fi
}

# wait_for_env NAME "what adds it": loops until the integration has created NAME.
wait_for_env() {
  local name="$1" source="$2"
  until has_env "$name"; do
    warn "$name isn't on the project yet (it comes from $source)."
    if ! confirm "Check again?"; then
      SKIPPED+=("$name from $source")
      return 0
    fi
  done
  ON_VERCEL+=("$name")
  printf '  %s✓ found%s %s on Vercel\n' "$GREEN" "$RESET" "$name"
}

run_wizard() {
cd "$(dirname "${BASH_SOURCE[0]}")/.."

TOTAL_STAGES=7

banner "HomeKeeper → Vercel setup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Log in to Vercel"
say "The Vercel CLI runs through npx, so there's nothing to install."
if who=$("${VERCEL[@]}" whoami </dev/null 2>/dev/null) && [[ -n "$who" ]]; then
  printf '  %s✓ already logged in as%s %s\n' "$GREEN" "$RESET" "$who"
  confirm "Use this account?" || "${VERCEL[@]}" login
else
  step "Pick how to log in (GitHub is easiest); a browser tab opens to confirm."
  "${VERCEL[@]}" login
fi
pause "Logged in? Press Enter"

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Create and link the Vercel project"
if [[ -f .env.local ]]; then
  cp .env.local .env.local.pglite.bak
  note "Backed up .env.local → .env.local.pglite.bak (local dev stays on PGlite)."
fi
say "Answer the prompts like this:"
step "Set up this directory? → yes"
step "Which scope? → your personal account"
step "Link to an existing project? → no"
step "Project name → homekeeper   ·   code directory → ./   ·   modify settings? → no"
step "Connect the GitHub repo hdavis094/homekeeper? → yes (pushes to main then deploy)"
warn "If it offers to pull environment variables into .env.local, answer NO."
pause "Press Enter to run 'vercel link'"
"${VERCEL[@]}" link
if [[ -f .env.local.pglite.bak ]] && ! cmp -s .env.local .env.local.pglite.bak; then
  cp .env.local.pglite.bak .env.local
  note "Restored your local .env.local."
fi
pause "Linked? Press Enter"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Database: Neon Postgres"
open_url "https://vercel.com/dashboard"
step "Open the homekeeper project → Storage tab → Create Database."
step "Choose Neon (Serverless Postgres) → Continue → accept the Neon terms."
step "Region: US East (N. Virginia / Washington, D.C.), next to Vercel's default functions."
step "Plan: Free. Name: homekeeper → Create."
step "Connect it to the project for Development, Preview and Production."
note "Leave the env var prefix empty so the variable is named DATABASE_URL."
pause "Done? Press Enter and I'll check the project"
wait_for_env DATABASE_URL "the Neon integration"

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "File storage: Vercel Blob (receipt and item photos)"
step "Same project → Storage tab → Create Database → Blob → Continue."
step "Name: homekeeper-files. If it asks for access, pick Public."
step "Create, then connect it to Development, Preview and Production."
pause "Done? Press Enter and I'll check the project"
wait_for_env BLOB_READ_WRITE_TOKEN "the Blob store"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Email: Resend API key"
open_url "https://resend.com/api-keys"
step "Sign up or log in (note which email you use)."
step "API Keys → Create API Key → name: homekeeper, permission: Sending access → Add."
step "Copy the key (starts with re_). Resend shows it only once."
if has_env RESEND_API_KEY && ! confirm "RESEND_API_KEY is already on Vercel. Replace it?"; then
  ON_VERCEL+=("RESEND_API_KEY")
else
  ask_secret RESEND_API_KEY "Paste the Resend API key:"
  vercel_env RESEND_API_KEY "$RESEND_API_KEY"
fi
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Email: sender address"
say "Without your own domain, Resend sends from onboarding@resend.dev and only"
say "to the email you signed up to Resend with. That's enough to try reminders."
note "With a domain: Resend → Domains → Add Domain, add its DNS records, then use"
note "e.g. HomeKeeper <reminders@yourdomain.com>. You can change this later."
ask EMAIL_FROM "Sender [Enter for HomeKeeper <onboarding@resend.dev>]:"
[[ -n "$EMAIL_FROM" ]] || EMAIL_FROM="HomeKeeper <onboarding@resend.dev>"
vercel_env EMAIL_FROM "$EMAIL_FROM"
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "App secrets (generated for you)"
say "BETTER_AUTH_SECRET signs logins; CRON_SECRET lets only Vercel Cron call the"
say "daily reminder job. Both are random and never leave Vercel."
for name in BETTER_AUTH_SECRET CRON_SECRET; do
  if has_env "$name"; then
    note "$name already exists; keeping it (replacing it would log everyone out)."
    ON_VERCEL+=("$name")
  elif [[ "$name" == BETTER_AUTH_SECRET ]]; then
    vercel_env "$name" "$(openssl rand -base64 32)"
  else
    vercel_env "$name" "$(openssl rand -hex 32)"
  fi
done
pause

finish
(( ${#ON_VERCEL[@]} )) && note "On Vercel (production): ${ON_VERCEL[*]}"
note "Local .env.local still uses PGlite (backup: .env.local.pglite.bak)."
printf '\n  %sNext: tell Claude "done". It migrates and seeds Neon, deploys,\n' "$BOLD"
printf '  sets BETTER_AUTH_URL to the live URL, and runs the e2e suite against it.%s\n\n' "$RESET"
}

run_wizard "$@"; exit
